  ["cpp.title.desc_75"] = "Leading a Guild.",
  ["cpp.title.desc_76"] = "Only a true devotee to the cause of the ancient Iks and their lost legacy may step up to the rank of proconsul.",
  ["cpp.title.desc_77"] = "Adjust your crown and handle it.",
  ["cpp.title.desc_78"] = "Unlocked the full Golden Outfit.",
  ["cpp.title.desc_79"] = "Challenged Ahau, guardian of Iksupan, in traditional Iks warrior attire.",
  ["cpp.title.desc_8"] = "Unlocked 50 or more Mounts.",
  ["cpp.title.desc_80"] = "Called to the court of Bounac by Kesar the Younger himself.",
  ["cpp.title.desc_81"] = "Awarded exclusively to stalwart heroes keeping the faith under all circumstances.",
  ["cpp.title.desc_82"] = "Some discoveries are reserved to only the most experienced adventurers. Until the next frontier opens on the horizon.",
  ["cpp.title.desc_83"] = "Awarded only to true connoisseurs undertaking even the most exotic culinary escapades.",
  ["cpp.title.desc_84"] = "Forging through battle after battle like a true gladiator.",
  ["cpp.title.desc_85"] = "Reached 2000 charm points. Quite beastly!",
  ["cpp.title.desc_86"] = "When the hunter becomes the hunted, perseverance decides the game.",
  ["cpp.title.desc_87"] = "Killing some snarky cave rats is helpful, killing over ten thousand of them is a statement.",
  ["cpp.title.desc_88"] = "Awarded for great help in the battle against Gaz'haragoth.",
  ["cpp.title.desc_89"] = "You prevailed during the battle of Bounac and broke the siege that held Bounac's people in its firm grasp.",
  ["cpp.title.desc_9"] = "Unlocked 10 or more Outfits.",
  ["cpp.title.desc_90"] = "Defeat Morshabaal 5 times.",
  ["cpp.title.desc_91"] = "Followed the trail of the Planestrider to the end.",
  ["cpp.title.desc_92"] = "Anywhere in time or space.",
  ["cpp.title.desc_93"] = "Reach 15,000 boss points.",
