  ["data.otservbr.global.lib.functions.players.L64.1624"] = "You have received a fame point.",
  ["data.otservbr.global.npc.a.bearded.woman.L144.674"] = "GET ME OUT OF HERE! NOW!",
  ["data.otservbr.global.npc.a.beautiful.girl.L53.318"] = "So you have come, |PLAYERNAME|. I hoped you would not...",
  ["data.otservbr.global.npc.a.beggar.L82.1060"] = "Hi! What is it, what d'ye {want}?",
