  ["data.otservbr.global.npc.ambassador.of.rathleton.L87.344"] = "Well, bye then.",
  ["data.otservbr.global.npc.amber.L426.528"] = "Yeah, see you later.",
  ["data.otservbr.global.npc.amber.L427.529"] = "See you later, |PLAYERNAME|.",
  ["data.otservbr.global.npc.amber.L428.530"] = "Oh hello, nice to see you |PLAYERNAME|. Are you here to hear some stories of my {adventures} or do you need {help}?",
  ["data.otservbr.global.npc.anderson.L100.133"] = "Ahoi, young man |PLAYERNAME| and welcome to the Nordic Tibia Ferries. If you need a {passage}, let me know.",
  ["data.otservbr.global.npc.anderson.L101.134"] = "Good bye. You are welcome.",
  ["data.otservbr.global.npc.andrew.lyze.L101.514"] = "Hello, I am the warden of this {monument}. The {sarcophagus} in front of you was established to prevent people from going {down} there. But I doubt that this step is sufficient.",
  ["data.otservbr.global.npc.andrew.lyze.L103.515"] = "Well, let's see if your mission was successful. Just bring me all needed {materials}.",
  ["data.otservbr.global.npc.andrew.lyze.L105.516"] = "If you dug up all three crystals of sufficient quantity and obtained the poison gland, the charging of your compass can start! For the very first time it will be charged by the violet crystal. Ready to {unleash} the power of the crystals?",
  ["data.otservbr.global.npc.andrew.lyze.L107.517"] = "Greetings.",
  ["data.otservbr.global.npc.andrew.lyze.L263.518"] = "Well, bye then.",
  ["data.otservbr.global.npc.andrew.lyze.L264.519"] = "Good bye.",
  ["data.otservbr.global.npc.anerui.L71.1487"] = "Ashari |PLAYERNAME|.",
  ["data.otservbr.global.npc.anerui.L72.1488"] = "Asha Thrazi.",
  ["data.otservbr.global.npc.anerui.L73.1489"] = "Asha Thrazi.",
  ["data.otservbr.global.npc.aneus.L130.1323"] = "Greetings adventurer |PLAYERNAME|. What leads you to me?",
  ["data.otservbr.global.npc.aneus.L131.1324"] = "Good bye and take care of you!",
  ["data.otservbr.global.npc.angelina.L58.143"] = "The gods must be praised that I am finally saved. I do not have many worldly possessions, but please accept a small reward, do you?",
  ["data.otservbr.global.npc.angelina.L60.144"] = "Thanks for saving my life! Should I teleport you out of the Dark Cathedral?",
  ["data.otservbr.global.npc.angelina.L84.145"] = "May the gods bless you.",
  ["data.otservbr.global.npc.angelina.L85.146"] = "May the gods bless you.",
  ["data.otservbr.global.npc.angelo.L153.1447"] = "Well, bye then.",
  ["data.otservbr.global.npc.angelo.L58.1443"] = "The Druid of Crunor? He told you that a new cave appeared here? That's right. I'm the head of a {project} that tries to find out more about this new {area}.",
  ["data.otservbr.global.npc.angelo.L60.1444"] = "Just get out of my way! You killed this beautiful creature. I have nothing more to say. Damn druid of Crunor!",
  ["data.otservbr.global.npc.angelo.L62.1445"] = "How is your {mission} going?",
  ["data.otservbr.global.npc.angelo.L64.1446"] = "The Druid of Crunor? He told you that a new cave appeared here? That's right. I'm the head of a project that tries to find out more about this new area.",
  ["data.otservbr.global.npc.angus.L633.1450"] = "Greetings, what can I do for you?",
  ["data.otservbr.global.npc.appaloosa.L109.1145"] = "Salutations, |PLAYERNAME| I guess you are here for the {horses}.",
