  ["data.otservbr.global.npc.pompan.L126.272"] = "Keep in mind you won't find better offers here. Just browse through my wares.",
  ["data.otservbr.global.npc.prezil.L143.719"] = "Welcome, young |PLAYERNAME|! If you are heavily wounded or poisoned, I can {heal} you for free.",
  ["data.otservbr.global.npc.prezil.L144.720"] = "Remember: If you are heavily wounded or poisoned, I can heal you for free.",
  ["data.otservbr.global.npc.prezil.L145.721"] = "May the gods bless you, |PLAYERNAME|!",
  ["data.otservbr.global.npc.puffels.L218.811"] = "Yeah, another fool {disturbing} me, what a joy.",
  ["data.otservbr.global.npc.puffels.L219.812"] = "Whatever.",
  ["data.otservbr.global.npc.puffels.L220.813"] = "Whatever.",
  ["data.otservbr.global.npc.pukosch.L87.1589"] = "Welcome, |PLAYERNAME|! Do you feel adventurous? Do you want a weekly {ticket} for the ore wagon system here? You can use it right here to get to the centre of Kazordoon!",
  ["data.otservbr.global.npc.pukosch.L88.1590"] = "Hope to see you again.",
  ["data.otservbr.global.npc.pydar.L96.217"] = "Be greeted |PLAYERNAME|! I can smell the scent of a phoenix on you!",
  ["data.otservbr.global.npc.pydar.L97.218"] = "May the fire in your heart never die, |PLAYERNAME|!",
  ["data.otservbr.global.npc.pydar.L98.219"] = "May the fire in your heart never die.",
