  ["monster.azerus.desc"] = "Azerus",
  ["monster.azerus.name"] = "Azerus",
  ["monster.azerus.voice_1"] = "The ultimate will finally consume this unworthy existence!",
  ["monster.azerus.voice_10"] = "Do you really think you could beat me?",
  ["monster.azerus.voice_11"] = "Even without Yalahari shields, I'm still invincible!",
  ["monster.azerus.voice_12"] = "Creation must be undone! We will join the ultimate in the annihiliverse!",
  ["monster.azerus.voice_13"] = "The rift is tearing at me, I can't control it much longer ... Master, where are you?",
  ["monster.azerus.voice_14"] = "Even gods are HIS pawns and HE laughs about creation! And you are trying to stop his minions?",
  ["monster.azerus.voice_15"] = "Don't you understand? Gods, Yalarahi, Humans we are all doing HIS bidding all the time!",
  ["monster.azerus.voice_2"] = "My masters and I will tear down barriers and join the ultimate in its realm!",
  ["monster.azerus.voice_3"] = "The power of the Yalahari will all be mine!",
  ["monster.azerus.voice_4"] = "We will open the rift for a new time to come!",
  ["monster.azerus.voice_5"] = "He who has returned from beyond has taught me secrets you can't even grasp!",
  ["monster.azerus.voice_6"] = "The end of times has come!",
  ["monster.azerus.voice_7"] = "The great machinator will make his entrance soon!",
  ["monster.azerus.voice_8"] = "You might scratch my shields but they will never break!",
  ["monster.azerus.voice_9"] = "You can't hope to penetrate my shields!",
