  ["quests.demon_oak.sound_7"] = "ETERNAL PAIN AWAITS YOU! NICE REWARD, HUH?!?!",
  ["quests.demon_oak.sound_8"] = "YOU ARE GOING TO PAY FOR EACH HIT WITH DECADES OF TORTURE!!",
