  ["quests.demon_oak.voice_1"] = "Release me and you will be rewarded greatefully!",
  ["quests.demon_oak.voice_2"] = "What is this? Demon Legs lying here? Someone might have lost them!",
  ["quests.demon_oak.voice_3"] = "I'm trapped, come here and free me fast!!",
  ["quests.demon_oak.voice_4"] = "I can bring your beloved back from the dead, just release me!",
  ["quests.demon_oak.voice_5"] = "What a nice shiny golden armor. Come to me and you can have it!",
  ["quests.demon_oak.voice_6"] = "Find a way in here and release me! Pleeeease hurry!",
  ["quests.demon_oak.voice_7"] = "You can have my demon set, if you help me get out of here!",
