  ["scripts.actions_baeloc_nictros.say_1"] = "Now we fight together, brother!",
  ["scripts.actions_baeloc_nictros.say_2"] = "Brother! I need your assistance!",
  ["scripts.actions_baeloc_nictros.say_3"] = "My turn! Let me show you my skills!",
  ["scripts.actions_baeloc_nictros.say_4"] = "I'll step back now. Let's see how you handle my brother!",
  ["scripts.actions_baeloc_nictros.say_5"] = "Oh, man! You always get the fun!",
  ["scripts.actions_baeloc_nictros.say_6"] = "Indeed! It has been a while! As the elder one I request the right of the first battle!",
  ["scripts.actions_baeloc_nictros.say_7"] = "Ah look my Brother! Challengers! After all this time finally a chance to prove our skills!",
