  ["scripts.dolls.12043_1"] = "For zze emperor!",
  ["scripts.dolls.12043_2"] = "Hail!",
  ["scripts.dolls.12043_3"] = "Hail %s!",
  ["scripts.dolls.12904_1"] = "Mhausheausheu! What a FAIL! Mwahaha!",
  ["scripts.dolls.12904_2"] = "Hail %s! You are wearing old socks!",
  ["scripts.dolls.12904_3"] = "You are so unpopular even your own shadow refuses to follow you.",
  ["scripts.dolls.12904_4"] = "Have fun!",
  ["scripts.dolls.14764_1"] = "My powers are limitless!",
  ["scripts.dolls.14764_2"] = "Hail!",
  ["scripts.dolls.18343_1"] = "Hail!",
  ["scripts.dolls.18343_2"] = "Shhhhhh, please be quiet!",
  ["scripts.dolls.18343_3"] = "Books are great!! Aren't they?",
  ["scripts.dolls.21435_1"] = "I can hear their whisperings... Revenge!",
  ["scripts.dolls.21435_2"] = "You shall feel pain and terror, %s",
  ["scripts.dolls.21435_3"] = "I do not need a sword to slaughter you",
  ["scripts.dolls.21435_4"] = "My sword is broken, but my spirit is not dead",
  ["scripts.dolls.21435_5"] = "I can say 469 and more...",
  ["scripts.dolls.21435_6"] = "My dark magic lies on the world",
  ["scripts.dolls.21947_1"] = "Hail!",
  ["scripts.dolls.21947_2"] = "Don't be afraid of the darkness!",
  ["scripts.dolls.21947_3"] = "Feel lucky, %s!",
  ["scripts.dolls.21947_4"] = "Purrrrrrr!",
  ["scripts.dolls.21962_1"] = "Hail! (União&Força)",
  ["scripts.dolls.21962_2"] = "Hail %s! (União&Força)",
  ["scripts.dolls.21962_3"] = "Only the real killers can touch me!",
  ["scripts.dolls.21962_4"] = "The path of assassin is found in death, DIE!",
  ["scripts.dolls.21962_5"] = "<FART...> Ahhh... silent and deadly...",
  ["scripts.dolls.22120_1"] = "Silence! I smell something!",
  ["scripts.dolls.22120_2"] = "Let me guide you, %s!",
  ["scripts.dolls.22120_3"] = "I have a bad feeling about this.",
  ["scripts.dolls.22120_4"] = "Watch your steps - we found the pit latrine.",
  ["scripts.dolls.5080_1"] = "Hug me!",
  ["scripts.dolls.5668_1"] = "It's not winning that matters, but winning in style.",
  ["scripts.dolls.5668_10"] = "Five steps east, fourteen steps south, two steps north and seventeen steps west!",
  ["scripts.dolls.5668_2"] = "Today's your lucky day. Probably.",
  ["scripts.dolls.5668_3"] = "Do not meddle in the affairs of dragons, for you are crunchy and taste good with ketchup.",
  ["scripts.dolls.5668_4"] = "That is one stupid question.",
  ["scripts.dolls.5668_5"] = "You'll need more rum for that.",
  ["scripts.dolls.5668_6"] = "Do or do not. There is no try.",
  ["scripts.dolls.5668_7"] = "You should do something you always wanted to.",
  ["scripts.dolls.5668_8"] = "If you walk under a ladder and it falls down on you it probably means bad luck.",
  ["scripts.dolls.5668_9"] = "Never say 'oops'. Always say 'Ah, interesting!'",
  ["scripts.dolls.6387_1"] = "Merry Christmas %s.",
  ["scripts.dolls.6511_1"] = "Ho ho ho",
