  ["scripts.dolls.6566_2"] = "Zchhhhhh!",
  ["scripts.dolls.6566_3"] = "Grooaaaaar*cough*",
  ["scripts.dolls.6566_4"] = "Aaa... CHOO!",
  ["scripts.dolls.6566_5"] = "You... will.... burn!!",
  ["scripts.dolls.8146_1"] = "ARE YOU PREPARED TO FACE YOUR DESTINY?",
